SELECT mutagenesis.effect, mutagenesis.position_start, mutagenesis.position_end, mutagenesis.description
FROM mutagenesis
WHERE protein_id = (SELECT protein_id FROM proteins WHERE entry = 'P04637');

SELECT COUNT(*) AS total_proteins  
FROM disease_involvement  
WHERE COUNT(*) > 50;

SELECT AVG(binding_sites.protein_id) AS average_binding_sites  
FROM binding_sites  
JOIN proteins ON binding_sites.protein_id = proteins.protein_id;

SELECT domain_name, COUNT(*) AS count
FROM topological_domains
GROUP BY domain_name;

SELECT COUNT(DISTINCT protein_id) AS total_proteins
FROM mutagenesis
WHERE COUNT(*) > 10;

SELECT COUNT(*) FROM binding_sites
WHERE ligand = 'Zn(2+)'
  AND NOT (SELECT ligand FROM binding_sites WHERE ligand = 'Ca(2+)');
